CREATE TABLE IF NOT EXISTS transportation_requests (id TEXT PRIMARY KEY,created_at TEXT NOT NULL,status TEXT NOT NULL,family_name TEXT NOT NULL,phone TEXT NOT NULL,email TEXT,children TEXT,from_address TEXT NOT NULL,from_lat TEXT,from_lng TEXT,to_address TEXT NOT NULL,to_lat TEXT,to_lng TEXT,details TEXT);CREATE TABLE IF NOT EXISTS rental_requests (id TEXT PRIMARY KEY,created_at TEXT NOT NULL,status TEXT NOT NULL,full_name TEXT NOT NULL,phone TEXT NOT NULL,email TEXT,passengers TEXT,start_datetime TEXT NOT NULL,end_datetime TEXT NOT NULL,pickup_address TEXT NOT NULL,pickup_lat TEXT,pickup_lng TEXT,destination_address TEXT NOT NULL,destination_lat TEXT,destination_lng TEXT,trip_details TEXT,id_object_key TEXT NOT NULL,id_original_name TEXT);